func boolToInt(b bool) C.int {
	if b {
		return 1
	}
	return 0
}

func lastError() error {
	length := C.go_last_error_length()
	if length == 0 {
		return fmt.Errorf("unknown error")
	}
	buf := make([]byte, length+1)
	C.go_last_error_message((*C.char)(unsafe.Pointer(&buf[0])), C.int(length+1))
	return fmt.Errorf("%s", string(buf[:length]))
}

// Keep nil (None) distinct from a present, empty byte slice.
var emptyByte byte

func bytesToPtr(b []byte) (*C.uint8_t, C.size_t) {
	if b == nil {
		return nil, 0
	}
	if len(b) == 0 {
		return (*C.uint8_t)(unsafe.Pointer(&emptyByte)), 0
	}
	return (*C.uint8_t)(unsafe.Pointer(&b[0])), C.size_t(len(b))
}

// The callback must finish before its native token is freed.
func newCancellation(ctx context.Context) (unsafe.Pointer, func()) {
	cancel := C.go_cancellation_new()
	done := make(chan struct{})
	stop := context.AfterFunc(ctx, func() {
		C.go_cancellation_cancel(cancel)
		close(done)
	})
	return cancel, func() {
		if !stop() {
			<-done
		}
		C.go_cancellation_free(cancel)
	}
}

func bigIntToSignedBytes(n *big.Int) []byte {
	if n.Sign() == 0 {
		return []byte{0}
	}
	if n.Sign() > 0 {
		b := n.Bytes()
		if len(b) > 0 && b[0]&0x80 != 0 {
			b = append([]byte{0}, b...)
		}
		return b
	}
	bitLen := n.BitLen() + 1
	byteLen := (bitLen + 7) / 8
	mod := new(big.Int).Lsh(big.NewInt(1), uint(byteLen*8))
	b := new(big.Int).Add(n, mod).Bytes()
	for len(b) < byteLen {
		b = append([]byte{0xff}, b...)
	}
	return b
}

func bigIntFromSignedBytes(b []byte) *big.Int {
	if len(b) == 0 {
		return new(big.Int)
	}
	n := new(big.Int).SetBytes(b)
	if b[0]&0x80 != 0 {
		mod := new(big.Int).Lsh(big.NewInt(1), uint(len(b)*8))
		n.Sub(n, mod)
	}
	return n
}

// Spends is the high-level transaction builder that accumulates coins and applies actions to produce a spend bundle.
//
// All methods are safe for concurrent use from multiple goroutines.
// Call [Free] or [Close] to release the underlying memory, or rely on the
// attached runtime finalizer for automatic cleanup.
type Spends struct {
	ptr unsafe.Pointer
	mu  sync.RWMutex
}

// Free releases the underlying Rust object.
// Calling Free more than once or on a nil receiver is safe and has no effect.
// Free blocks until any concurrent method calls complete.
func (o *Spends) Free() {
	if o == nil {
		return
	}
	o.mu.Lock()
	defer o.mu.Unlock()
	if o.ptr == nil {
		return
	}
	C.go_spends_free(o.ptr)
	o.ptr = nil
}

// Close implements [io.Closer] by releasing the underlying resource.
// It is safe to call Close multiple times and concurrently with other methods.
func (o *Spends) Close() error {
	o.Free()
	return nil
}

// Clone returns a deep copy of the Spends.
func (o *Spends) Clone() (*Spends, error) {
	if o == nil {
		return nil, fmt.Errorf("object is nil or already freed")
	}
	o.mu.RLock()
	defer o.mu.RUnlock()
	if o.ptr == nil {
		return nil, fmt.Errorf("object is nil or already freed")
	}
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	var out unsafe.Pointer
	ret := C.go_spends_clone(o.ptr, &out)
	if ret != 0 {
		return nil, lastError()
	}
	clone := &Spends{ptr: out}
	runtime.SetFinalizer(clone, (*Spends).Free)
	return clone, nil
}

// NewSpends creates a new transaction builder with the given CLVM allocator and change puzzle hash.
func NewSpends(clvm *Clvm, changePuzzleHash []byte) (*Spends, error) {

	defer runtime.KeepAlive(clvm)
	var locks handleLocks
	if clvm == nil {
		return nil, fmt.Errorf("clvm is nil or already freed")
	}
	locks = append(locks, &clvm.mu)
	defer lockHandles(nil, locks...)()
	if clvm.ptr == nil {
		return nil, fmt.Errorf("clvm is nil or already freed")
	}

	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	changePuzzleHashPtr, changePuzzleHashLen := bytesToPtr(changePuzzleHash)

	var out unsafe.Pointer
	ret := C.go_spends_new(clvm.ptr, changePuzzleHashPtr, changePuzzleHashLen, &out)
	if ret != 0 {

		return nil, lastError()
	}
	obj := &Spends{ptr: out}
	runtime.SetFinalizer(obj, (*Spends).Free)
	return obj, nil
}

