// CreateBulletin creates a bulletin board singleton for publishing on-chain messages.
func (o *Clvm) CreateBulletin(parentCoinId []byte, hiddenPuzzleHash []byte, messages []*BulletinMessage) (*CreatedBulletin, error) {

	defer runtime.KeepAlive(o)
	defer runtime.KeepAlive(messages)
	var locks handleLocks
	if o == nil {
		return nil, fmt.Errorf("object is nil or already freed")
	}
	locks = append(locks, &o.mu)
	for _, item := range messages {
		if item == nil {
			return nil, fmt.Errorf("messages is nil or already freed")
		}
		locks = append(locks, &item.mu)
	}
	defer lockHandles(nil, locks...)()
	if o.ptr == nil {
		return nil, fmt.Errorf("object is nil or already freed")
	}
	for _, item := range messages {
		if item.ptr == nil {
			return nil, fmt.Errorf("messages is nil or already freed")
		}
	}

	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	parentCoinIdPtr, parentCoinIdLen := bytesToPtr(parentCoinId)
	hiddenPuzzleHashPtr, hiddenPuzzleHashLen := bytesToPtr(hiddenPuzzleHash)
	messagesPtrs := make([]unsafe.Pointer, len(messages))
	for i, item := range messages {
		messagesPtrs[i] = item.ptr
	}
	var messagesPtrsC *unsafe.Pointer
	if len(messagesPtrs) > 0 {
		messagesPtrsC = &messagesPtrs[0]
	}
	messagesLen := C.size_t(len(messages))

	var out unsafe.Pointer
	ret := C.go_clvm_create_bulletin(o.ptr, parentCoinIdPtr, parentCoinIdLen, hiddenPuzzleHashPtr, hiddenPuzzleHashLen, (*unsafe.Pointer)(unsafe.Pointer(messagesPtrsC)), messagesLen, &out)
	if ret != 0 {

		return nil, lastError()
	}
	obj := &CreatedBulletin{ptr: out}
	runtime.SetFinalizer(obj, (*CreatedBulletin).Free)
	return obj, nil
}

