	otherCatSpendsLen := C.size_t(len(otherCatSpends))

	var out unsafe.Pointer
	ret := C.go_reward_distributor_finish_spend(o.ptr, (*unsafe.Pointer)(unsafe.Pointer(otherCatSpendsPtrsC)), otherCatSpendsLen, &out)
